{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    node_to_idx = {node: i for i, node in enumerate(nodes)}
    n = len(nodes)

    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        w = max(core[u], core[v], d)
        edges.append((w, u, v))

    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        iu = node_to_idx[u]
        iv = node_to_idx[v]
        if union(iu, iv):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Disconnected graph: cannot form MST")

    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
